function hx(h){return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];}
console.log('red RGB: '+hx('#FF0000').join(','));
console.log('red photon E: '+(6.626e-34*3e8/700e-9).toExponential(2)+' J');

var r=[255,0,0],y=[255,255,0];
var o=r.map(function(v,i){return Math.round((v+y[i])/2);});
console.log('red+yellow mix: rgb('+o.join(',')+')');

var E=6.626e-34*3e8/470e-9;
console.log('blue photon: '+E.toExponential(2)+' J');
console.log('vs red: '+(E/(6.626e-34*3e8/700e-9)).toFixed(2)+'x more');

var cols=[[255,0,0],[0,255,0],[0,0,255]];
